var preimageSizeFZF = function(k) {
    function trailingZeroes(x) {
        let res = 0;
        while (x > 0) {
            res += Math.floor(x / 5);
            x = Math.floor(x / 5);
        }
        return res;
    }
    let left = 0, right = 5 * (k + 1);
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        const zeros = trailingZeroes(mid);
        if (zeros === k) return 5;
        else if (zeros < k) left = mid + 1;
        else right = mid - 1;
    }
    return 0;
};
